import{fetchCohortJSON}from'./current-cohort-loader.js';import{fitGroups092,currentStatistics092}from'./match-fit-092.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number.isFinite(n)?'$'+Math.round(n/1000)+'k':'Unassessed',labels={development:'Development',holdout:'Original holdout',holdout049:'Fresh holdout',holdout056:'Expansion holdout',grok075:'Grok evaluation'},degree=o=>o.routes.some(r=>['college','graduate'].includes(r.key));let data,rows=[],filtered=[],page=0,expanded=false;
const link=r=>'/model-results-104.html?model='+encodeURIComponent(r.id)+'&arm='+($('arm').value==='previous'?'control':'targeted');
function hydrate(){rows=data.rows.map(r=>{const arm=r.arms[$('arm').value],offers=arm.offers.map(([id,score,level,mixed,covers,fitLevel])=>({...data.catalog[id],correlation:score===null?null:score/1e6,top:level===2,candidate:level===0,mixedInterests:mixed,lifestyleCovers:covers,fitLevel}));return{...r,asked:arm.asked,unknown:arm.unknown,supported:offers.filter(x=>!x.candidate),candidates:offers.filter(x=>x.candidate)};});}
function render(){const c=$('cohort').value,q=$('search').value.toLowerCase(),status=$('status').value;filtered=rows.filter(r=>(c==='both'||c==='original'&&r.cohort!=='grok075'||r.cohort===c)&&(!q||[r.id,r.name,...r.supported.map(o=>o.title),...r.candidates.map(o=>o.title)].join(' ').toLowerCase().includes(q))&&(status==='all'||status==='noTop'&&!r.supported.some(o=>o.top)||status==='degree'&&r.supported.some(o=>o.top&&degree(o))||status==='noDegree'&&!r.supported.some(o=>o.top&&degree(o))));
 const groups=[...(['both','original'].includes(c)&&new Set(filtered.filter(r=>r.cohort!=='grok075').map(r=>r.cohort)).size>1?[['First cohort · in view',filtered.filter(r=>r.cohort!=='grok075')]]:[]),['Grok evaluation',filtered.filter(r=>r.cohort==='grok075')],...Object.entries(labels).filter(([id])=>id!=='grok075').map(([id,label])=>[label,filtered.filter(r=>r.cohort===id)])].filter(x=>x[1].length);$('stats').innerHTML=groups.map(([label,rs])=>{const s=currentStatistics092(rs),other=rs.filter(r=>r.supported.some(o=>!o.top)).length,explore=rs.filter(r=>r.candidates.length).length;return`<article><h3>${h(label)} · ${s.models}</h3><strong>${s.top} Top · ${s.degree} degree</strong><p>No-degree Top ${s.noncollege} · Other ${other} · Explore ${explore}</p><small>Pay ≥ target ${s.lifestyle} · ${(rs.reduce((n,r)=>n+r.asked,0)/rs.length).toFixed(0)} follow-ups</small></article>`;}).join('')||'No models in this view.';
 $('context').textContent=($('arm').value==='previous'?'Current research control':'Replacement experiment · research only')+' · Fresh 60 profiler + 24 adaptive follow-ups. Lifestyle is separate. No accumulated answers. '+filtered.length.toLocaleString()+' models in view.';page=Math.min(page,Math.max(0,Math.ceil(filtered.length/25)-1));
 $('students').innerHTML=filtered.slice(page*25,(page+1)*25).map(r=>{const url=link(r),career=o=>`<li><a class="fit-career" href="${url}">${h(o.title)}</a><div class="fit-meta"><strong>${money(o.entry)}</strong><span>${h(o.routes.map(x=>x.label).join(' / '))}</span><span class="support-chip ${o.candidate?'pending':o.top?'top':'supported'}">${o.candidate?'Confirm':o.top?'Top':'Supported'}</span>${!Number.isFinite(o.correlation)?'<span>Interest score unavailable</span>':''}${o.mixedInterests?'<span>Mixed evidence</span>':''}</div></li>`;return`<tr><td><a class="student-name" href="${url}">${h(r.name)}</a><small>${h(r.id)}<br>${h(labels[r.cohort])}</small><a class="journey-link" href="${url}">Open results after questions →</a><small>60 + ${r.asked} questions<br>${r.unknown} follow-ups unknown</small></td>${fitGroups092(r).map(g=>({...g,offers:g.offers.sort((a,b)=>Number(b.top)-Number(a.top)||Number(a.candidate)-Number(b.candidate))})).map(g=>`<td class="fit-level-cell ${g.id}">${g.offers.length?'<ul class="career-list">'+(expanded?g.offers:g.offers.slice(0,3)).map(career).join('')+'</ul>'+(!expanded&&g.offers.length>3?'<details><summary>'+String(g.offers.length-3)+' more</summary><ul class="career-list">'+g.offers.slice(3).map(career).join('')+'</ul></details>':''):'—'}</td>`).join('')}<td><b>${money(r.lifestyle.target)} target</b><p>${r.supported.filter(o=>o.lifestyleCovers===true).length} supported options meet target</p><a href="${url}">Pay comparison →</a></td></tr>`;}).join('');$('page').textContent=(filtered.length?page*25+1:0)+'–'+Math.min(filtered.length,(page+1)*25)+' of '+filtered.length;$('prev').disabled=!page;$('next').disabled=(page+1)*25>=filtered.length;
}
for(const id of['cohort','status','search'])$(id).addEventListener('input',()=>{page=0;render();});$('arm').onchange=()=>{hydrate();page=0;render();};$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};$('expand-all').onclick=()=>{expanded=!expanded;$('expand-all').setAttribute('aria-pressed',String(expanded));$('expand-all').textContent=expanded?'Collapse careers':'Expand all careers';render();};$('download').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"',csv=[['Student','Model','Cohort','Fit','Career','Status','Education','Annual pay','Lifestyle target'],...filtered.flatMap(r=>fitGroups092(r).flatMap(g=>g.offers.map(o=>[r.name,r.id,r.cohort,g.label,o.title,o.candidate?'Confirm':o.top?'Top':'Supported',o.routes.map(x=>x.label).join('; '),o.entry,r.lifestyle.target])))].map(r=>r.map(cell).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='fresh-student-matches-104.csv';a.click();URL.revokeObjectURL(a.href);};
try{data=await fetchCohortJSON('/developer/matrix-104.json.gz');const p=new URL(location.href).searchParams;$('arm').value=p.get('arm')==='targeted'?'targeted':'previous';if([...$('cohort').options].some(o=>o.value===p.get('cohort')))$('cohort').value=p.get('cohort');$('search').value=p.get('model')||'';hydrate();render();}catch(e){$('stats').textContent='Could not load the fresh matrix: '+e.message;}
